stageCss:
#stage .dx-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .dx-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .dx-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .dx-mark svg{ width:25px; height:25px; }
#stage .dx-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .dx-time{ margin-left:auto; flex-shrink:0; }
#stage .dx-time b{
  color:#fff; font-family:var(--font-mono); font-size:30px; font-weight:700;
  font-variant-numeric:tabular-nums;
}
#stage .dx-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .dx-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .dx-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .dx-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .dx-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .dx-health.warn b{ color:var(--warn); }
#stage .dx-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .dx-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .dx-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .dx-body{ position:relative; flex:1; min-height:0; }
#stage .dx-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .dx-sc.on{ opacity:1; transform:none; }
#stage .dx-sc.whip{ animation:dx-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .dx-inc{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ------------------------------------------------------------- the chart -- */
#stage .dx-chart{
  position:relative; flex:1; min-height:0; display:flex; flex-direction:column; gap:12px;
  padding:18px 22px 14px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.1), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.4);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .dx-chart.bad{
  border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.22), 0 0 56px rgba(244,74,106,.16);
}
#stage .dx-chart-h{ display:flex; align-items:baseline; gap:14px; }
#stage .dx-chart-n{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:700; letter-spacing:1.4px; }
#stage .dx-chart-v{ margin-left:auto; display:flex; align-items:baseline; gap:8px; white-space:nowrap; }
#stage .dx-chart-v b{
  color:#fff; font-family:var(--font-mono); font-size:34px; font-weight:800;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .dx-chart.bad .dx-chart-v b{ color:var(--danger); }
#stage .dx-chart-v i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
/* Fourteen half-hour buckets. Heights are set from stage code — the shape of
   this chart is the story. */
#stage .dx-bars{
  flex:1; min-height:0; display:flex; align-items:flex-end; gap:7px;
  padding-bottom:2px; border-bottom:1.5px solid var(--border);
}
#stage .dx-bars i{
  flex:1; display:block; height:4%; border-radius:6px 6px 2px 2px;
  background:linear-gradient(180deg, var(--accent-cyan), rgba(34,211,238,.35));
  transition:height .55s cubic-bezier(.22,1,.36,1), background .3s ease;
}
#stage .dx-bars i.hot{ background:linear-gradient(180deg,#F0A64A,rgba(240,166,74,.35)); }
#stage .dx-bars i.gone{ background:linear-gradient(180deg,#F44A6A,rgba(244,74,106,.3)); }
#stage .dx-axis{
  display:flex; align-items:center; justify-content:space-between;
  color:var(--text-dim); font-family:var(--font-mono); font-size:16px; font-weight:600;
}
#stage .dx-band{
  position:absolute; top:66px; left:50%; transform:translateX(-50%); z-index:3;
  padding:7px 15px; border-radius:100px; white-space:nowrap; opacity:0;
  border:1.5px solid rgba(244,74,106,.6); background:#2a0d16; color:var(--danger);
  font-family:var(--font-mono); font-size:16px; font-weight:800; letter-spacing:1.2px;
  transition:opacity .3s ease;
}
#stage .dx-band.on{ opacity:1; animation:dx-alert 1s ease-in-out infinite; }

/* ------------------------------------------------------------- detail ---- */
#stage .dx-detail{
  height:206px; flex-shrink:0; display:flex; flex-direction:column; gap:12px; justify-content:center;
  padding:18px 22px; border-radius:24px;
  background:rgba(20,27,43,.62); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .dx-detail.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.07); }
#stage .dx-detail.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.07); }
#stage .dx-d-h{ color:#fff; font-size:23px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .dx-d-body{ display:flex; flex-direction:column; gap:7px; }
#stage .dx-d{
  padding:9px 13px; border-radius:10px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  background:rgba(14,20,32,.72); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  transition:background .3s ease, border-color .3s ease, color .3s ease, opacity .3s ease;
}
#stage .dx-d.ok{ border-color:rgba(63,185,80,.4); background:rgba(63,185,80,.09); color:#bff0c4; }
#stage .dx-d.warn{ border-color:rgba(240,166,74,.45); background:rgba(240,166,74,.09); color:var(--warn); }
#stage .dx-d.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); color:#ffd0d9; }
#stage .dx-d.off{ opacity:.35; }
#stage .dx-d-b{
  align-self:flex-start; padding:7px 15px; border-radius:100px; white-space:nowrap;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7); color:var(--text-dim);
  font-family:var(--font-mono); font-size:16px; font-weight:700;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .dx-d-b.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.14); color:var(--danger); }
#stage .dx-d-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }

#stage .dx-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .dx-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:1.6px;
}
#stage .dx-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .dx-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .dx-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .dx-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .dx-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ========================= SCENE 2 · THE FOUR LINES ==================== */
#stage .dx-fix{
  height:100%; display:flex; flex-direction:column; justify-content:center; gap:20px;
  padding:0 8px;
}
#stage .dx-fix-h{ display:flex; align-items:center; gap:14px; }
#stage .dx-fix-ic{
  width:56px; height:56px; border-radius:16px; flex-shrink:0; font-size:28px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(63,185,80,.14); border:1.5px solid rgba(63,185,80,.4);
}
#stage .dx-fix-n{ color:#fff; font-size:30px; font-weight:800; letter-spacing:-.4px; }
#stage .dx-fix-code{ display:flex; flex-direction:column; gap:12px; }
#stage .dx-f{
  display:flex; align-items:center; gap:14px;
  padding:18px 18px; border-radius:18px; white-space:nowrap; overflow:hidden;
  background:rgba(14,20,32,.75); border:1.5px solid rgba(63,185,80,.35);
  color:var(--text-primary); font-family:var(--font-mono); font-size:20px; font-weight:600;
}
#stage .dx-f i{
  flex-shrink:0; width:28px; height:28px; border-radius:8px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(63,185,80,.18); color:var(--success);
  font-style:normal; font-size:16px; font-weight:800;
}
#stage .dx-f b{
  margin-left:auto; flex-shrink:0; padding:6px 13px; border-radius:9px;
  background:rgba(139,149,167,.12); color:var(--text-dim);
  font-size:16px; font-weight:700;
}
#stage .dx-f#dx-f-2{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.08); }
#stage .dx-f#dx-f-2 i{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .dx-f#dx-f-2 b{ background:rgba(244,74,106,.18); color:var(--danger); }
#stage .dx-fix-b{
  padding:16px 18px; border-radius:16px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border); color:var(--text-primary);
  font-size:21px; font-weight:600;
}

/* ========================== SCENE 3 · THE PAYOFF ======================= */
#stage .dx-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .dx-badge{
  width:130px; height:130px; border-radius:36px; font-size:58px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(244,74,106,.26), rgba(240,166,74,.12));
  border:2px solid rgba(244,74,106,.55);
  box-shadow:0 0 0 1px rgba(244,74,106,.28), 0 0 80px rgba(244,74,106,.26);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .dx-badge-l{ color:var(--danger); font-family:var(--font-mono); font-size:17px; font-weight:800; letter-spacing:2px; }
#stage .dx-fin-h{ color:#fff; font-size:66px; font-weight:900; line-height:1.12; letter-spacing:-2px; }
#stage .dx-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .dx-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .dx-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:21px; font-weight:700;
}
#stage .dx-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:860px;
  background:linear-gradient(90deg, rgba(244,74,106,.16), rgba(58,160,255,.16));
  border:1.5px solid rgba(58,160,255,.5); color:#fff;
  font-size:25px; font-weight:700; line-height:1.35;
}
#stage .dx-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes dx-alert{
  0%,100%{ box-shadow:0 0 0 0 rgba(244,74,106,.4); }
  50%{ box-shadow:0 0 0 10px rgba(244,74,106,0); }
}
@keyframes dx-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

