var DX = window.__DX || (window.__DX = {});
// The chart is the story, so bar heights are data the stages set directly.
DX.bars = function(heights, cls){
  var els = MSD.qa('#dx-bars i');
  els.forEach(function(el, i){
    el.style.height = (heights[i] == null ? 4 : heights[i]) + '%';
    el.classList.remove('hot');
    el.classList.remove('gone');
    if(cls && cls[i]) el.classList.add(cls[i]);
  });
};
DX.detail = function(head, lines, badge){
  MSD.q('#dx-d-h').textContent = head;
  for(var i = 0; i < 3; i++){
    var el = MSD.q('#dx-d-' + (i + 1));
    var row = lines[i];
    el.className = 'dx-d ' + (row && row[1] ? row[1] : '');
    el.textContent = row ? row[0] : '';
    if(!row) el.classList.add('off');
  }
  var b = MSD.q('#dx-d-b');
  b.textContent = badge[0];
  b.className = 'dx-d-b ' + (badge[1] || '');
};

MSD.cls('.dx-sc', 'on', false);
MSD.cls('#dx-sc-incident', 'on', true);
MSD.q('#dx-app').textContent = 'orders-queue · 14 March';
MSD.q('#dx-time-n').textContent = '09:12';
MSD.cls('#dx-health', 'warn', false);
MSD.cls('#dx-health', 'bad', false);
MSD.q('#dx-health-t').textContent = 'all green';
MSD.cls('#dx-chart', 'bad', false);
MSD.cls('#dx-band', 'on', false);
MSD.cls('#dx-detail', 'bad', false);
MSD.cls('#dx-detail', 'ok', false);
MSD.q('#dx-depth').textContent = '0';
MSD.hide('.dx-f');
MSD.hide('.dx-fin-p');
MSD.cls('#dx-strip', 'bad', false);
MSD.cls('#dx-strip', 'good', false);
MSD.q('#dx-strip-l').textContent = '09:12';
MSD.q('#dx-strip-t').textContent = 'A completely ordinary Tuesday deploy. This is the last calm frame.';

DX.bars([6, 5, 7, 6, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4]);
DX.detail('deploy 4f21a9 · orders-worker',
  [['rolling out 3 instances', 'ok'], ['health checks green', 'ok'], ['consumer connected', 'ok']],
  ['nothing looks wrong yet', '']);

MSD.after(700, function(){ MSD.punch('#dx-detail', 1); MSD.sfx.blip(1); });
MSD.after(1700, function(){ MSD.q('#dx-depth').textContent = '31'; });

var DX = window.__DX;

MSD.cls('.dx-sc', 'on', false);
MSD.cls('#dx-sc-incident', 'on', true);
MSD.cls('#dx-detail', 'ok', false);
MSD.q('#dx-time-n').textContent = '09:40';
MSD.cls('#dx-strip', 'good', false);
MSD.q('#dx-strip-l').textContent = '09:40';
MSD.q('#dx-strip-t').textContent = 'This part is fine. A queue absorbing a dead consumer is the whole point.';

DX.detail('orders-worker · crash loop',
  [['JsonException on OrderV2', 'bad'], ['restart 1 · 2 · 3 …', 'bad'], ['active consumers: 0', 'bad']],
  ['the queue is doing its job', '']);
MSD.cls('#dx-detail', 'bad', true);

MSD.after(300, function(){
  MSD.cls('#dx-band', 'on', true);
  MSD.cls('#dx-health', 'warn', true);
  MSD.q('#dx-health-t').textContent = 'consumer down';
  MSD.sfx.error();
});
MSD.after(800, function(){
  DX.bars([6, 5, 7, 22, 41, 58, 74, 4, 4, 4, 4, 4, 4, 4],
    [null, null, null, 'hot', 'hot', 'hot', 'hot']);
  MSD.q('#dx-depth').textContent = '3,180';
  MSD.sfx.blip(3);
});
MSD.after(1900, function(){
  DX.bars([6, 5, 7, 22, 41, 58, 74, 92, 4, 4, 4, 4, 4, 4],
    [null, null, null, 'hot', 'hot', 'hot', 'hot', 'hot']);
  MSD.q('#dx-depth').textContent = '4,318';
  MSD.q('#dx-time-n').textContent = '10:30';
});

var DX = window.__DX;

MSD.cls('.dx-sc', 'on', false);
MSD.cls('#dx-sc-incident', 'on', true);
MSD.cls('#dx-band', 'on', true);
MSD.cls('#dx-detail', 'ok', false);
MSD.cls('#dx-detail', 'bad', true);
MSD.q('#dx-time-n').textContent = '10:41';
MSD.cls('#dx-health', 'warn', true);
MSD.q('#dx-health-t').textContent = 'consumer down';
MSD.cls('#dx-strip', 'good', false);
MSD.cls('#dx-strip', 'bad', true);
MSD.q('#dx-strip-l').textContent = '10:41';
MSD.q('#dx-strip-t').textContent = 'A queue going down while nothing reads it is the wrongest thing on this screen.';

DX.detail('orders-worker · still crash looping',
  [['active consumers: 0', 'bad'], ['messages completed: 0', 'bad'], ['queue depth: falling', 'warn']],
  ['so where are they going?', 'bad']);

MSD.after(600, function(){
  DX.bars([6, 5, 7, 22, 41, 58, 74, 92, 68, 4, 4, 4, 4, 4],
    [null, null, null, 'hot', 'hot', 'hot', 'hot', 'hot', 'gone']);
  MSD.q('#dx-depth').textContent = '3,102';
  MSD.cls('#dx-chart', 'bad', true);
  MSD.sfx.error();
});
MSD.after(1500, function(){
  DX.bars([6, 5, 7, 22, 41, 58, 74, 92, 68, 44, 26, 4, 4, 4],
    [null, null, null, 'hot', 'hot', 'hot', 'hot', 'hot', 'gone', 'gone', 'gone']);
  MSD.q('#dx-depth').textContent = '1,190';
  MSD.q('#dx-time-n').textContent = '11:50';
  MSD.sfx.error();
});
MSD.after(2400, function(){
  DX.bars([6, 5, 7, 22, 41, 58, 74, 92, 68, 44, 26, 12, 6, 4],
    [null, null, null, 'hot', 'hot', 'hot', 'hot', 'hot', 'gone', 'gone', 'gone', 'gone', 'gone']);
  MSD.q('#dx-depth').textContent = '104';
  MSD.shake('#dx-chart');
  MSD.sfx.thud();
});

var DX = window.__DX;

MSD.cls('.dx-sc', 'on', false);
MSD.cls('#dx-sc-incident', 'on', true);
MSD.cls('#dx-band', 'on', true);
MSD.cls('#dx-chart', 'bad', true);
MSD.cls('#dx-detail', 'ok', false);
MSD.cls('#dx-detail', 'bad', true);
MSD.q('#dx-time-n').textContent = '12:15';
MSD.q('#dx-depth').textContent = '0';
MSD.cls('#dx-health', 'warn', false);
MSD.cls('#dx-health', 'bad', true);
MSD.q('#dx-health-t').textContent = 'looks recovered';
MSD.cls('#dx-strip', 'good', false);
MSD.cls('#dx-strip', 'bad', true);
MSD.q('#dx-strip-l').textContent = '12:15';
MSD.q('#dx-strip-t').textContent = 'Every dashboard we had said the incident was over.';

DX.bars([6, 5, 7, 22, 41, 58, 74, 92, 68, 44, 26, 12, 6, 4],
  [null, null, null, 'hot', 'hot', 'hot', 'hot', 'hot', 'gone', 'gone', 'gone', 'gone', 'gone']);

MSD.after(400, function(){
  DX.detail('where did 4,318 orders go?',
    [['dead-letter queue: 0', 'bad'], null, null],
    ['not dead-lettered', 'bad']);
  MSD.sfx.error();
});
MSD.after(1200, function(){
  DX.detail('where did 4,318 orders go?',
    [['dead-letter queue: 0', 'bad'], ['exceptions logged: 0', 'bad'], null],
    ['not failed either', 'bad']);
  MSD.sfx.error();
});
MSD.after(2000, function(){
  DX.detail('where did 4,318 orders go?',
    [['dead-letter queue: 0', 'bad'], ['exceptions logged: 0', 'bad'], ['deleted by the broker', 'bad']],
    ['expired, and dropped', 'bad']);
  MSD.shake('#dx-detail');
  MSD.sfx.thud();
});

var DX = window.__DX;

MSD.cls('.dx-sc', 'on', false);
MSD.cls('#dx-sc-incident', 'on', true);
MSD.cls('#dx-chart', 'bad', true);
MSD.cls('#dx-band', 'on', true);
MSD.cls('#dx-detail', 'ok', false);
MSD.cls('#dx-detail', 'bad', true);
MSD.q('#dx-time-n').textContent = '12:15';
MSD.cls('#dx-health', 'bad', true);
MSD.q('#dx-health-t').textContent = 'root cause';
MSD.cls('#dx-strip', 'good', false);
MSD.cls('#dx-strip', 'bad', true);
MSD.q('#dx-strip-l').textContent = 'CAUSE';
MSD.q('#dx-strip-t').textContent = 'A TTL is a delete instruction. Nobody reads it that way when they set it.';

MSD.after(400, function(){
  DX.detail('orders-queue · properties',
    [['DefaultMessageTimeToLive = 01:00:00', 'warn'], null, null],
    ['set on purpose, a year ago', '']);
  MSD.sfx.blip(2);
});
MSD.after(1300, function(){
  DX.detail('orders-queue · properties',
    [['DefaultMessageTimeToLive = 01:00:00', 'warn'],
     ['EnableDeadLetteringOnMessageExpiration = false', 'bad'], null],
    ['nobody set this. It is the default.', 'bad']);
  MSD.punch('#dx-detail', 4);
  MSD.sfx.error();
});
MSD.after(2300, function(){
  DX.detail('orders-queue · properties',
    [['DefaultMessageTimeToLive = 01:00:00', 'warn'],
     ['EnableDeadLetteringOnMessageExpiration = false', 'bad'],
     ['expired message → deleted, not dead-lettered', 'bad']],
    ['TTL + default = silent deletion', 'bad']);
  MSD.shake('#dx-detail');
  MSD.sfx.thud();
});

var DX = window.__DX;

MSD.cls('.dx-sc', 'on', false);
MSD.cls('#dx-sc-incident', 'on', true);
MSD.cls('#dx-band', 'on', true);
MSD.q('#dx-time-n').textContent = '12:15';
MSD.cls('#dx-strip', 'bad', false);
